-- ============================================================
-- スポット（spots）: 北アルプス山麓の5地域（#30）
-- ============================================================
-- docs/spec.md データ-1: 1地域8件以上、1地域でカテゴリ4種以上。description は2〜4文（120〜250字）。
-- - 実在し、一般に公開・営業している場所だけ。事実は公式・自治体・観光協会で確かめ、出典は docs/spot-sources.md に1件ずつ書く。
--   確かめられないことは書かない。営業時間・料金は変わるので、書くときは出典の値をそのまま使う。
-- - id は固定。形は 20000000-0000-4000-8000-00000000AANN（AA = 地域の id の末尾2桁、NN = 地域内の連番）。
-- - lat / lng の取り方（公式の座標・国土地理院のジオコーダー・OpenStreetMap など）もスポットごとに docs/spot-sources.md に書く。
-- - rating は docs/spot-scores.md（#61）の基準で 0.5 刻み。
-- - 穴場度（hidden_gem_score）は docs/spot-scores.md（#61）の基準で 1〜5 の整数。値と根拠は docs/spot-sources.md。
-- - image_path は写真を用意するまで null（#67）。予定のパスは docs/image-credits.md。
-- - 全国のほかの地域のスポットは #58 で足す（下の段）。

insert into public.spots
  (id, area_id, name, category, lat, lng, catchphrase, description, local_tip,
   best_time, stay_minutes, tags, rating, hidden_gem_score, image_path)
values
  -- 白馬村
  ('20000000-0000-4000-8000-000000000101', '10000000-0000-4000-8000-000000000001',
   '白馬塩の道温泉 倉下の湯', 'onsen', 36.709791, 137.848360,
   '舐めると塩辛い、褐色のかけ流しの湯',
   '松川のほとりで平成5年に掘り当てた「白馬塩の道温泉」の元湯。名前のとおり塩分を多く含み、舐めると塩辛い褐色のにごり湯を源泉かけ流しで使い、露天風呂からは北アルプスが見える。白馬駅から八方方面へ進み、白馬大橋を渡ってすぐ。無料駐車場は30台。',
   '白馬村・小谷村・小川村・大町市の住民は割引がある。営業時間は季節で変わるので公式サイトで確かめてから',
   '通年（年中無休）', 60, array['源泉かけ流し', '露天風呂', '北アルプスの眺め'], 4.0, 3, null),
  ('20000000-0000-4000-8000-000000000102', '10000000-0000-4000-8000-000000000001',
   '青鬼集落', 'history', 36.719869, 137.896329,
   '茅葺きの家と棚田が残る、今も暮らしのある山の集落',
   '標高約760mの山あいに、茅葺き（今は鉄板で覆う）の主屋14棟が等高線に沿って並ぶ集落で、国の重要伝統的建造物群保存地区。石垣で築いた約200枚の棚田は「日本の棚田百選」に選ばれ、幕末に集落24戸が掘った用水路「青鬼上堰」が今も潤す。車は集落入口の指定駐車場に停め、そこから歩く。',
   '人が暮らす集落なので、家の敷地や棚田のあぜには入らず静かに歩く。トイレは「お善鬼の館」を使う',
   '通年（青鬼神社の祭りは5月・9月・11月）', 60, array['重要伝統的建造物群保存地区', '棚田百選', '茅葺き'], 4.5, 3, null),
  ('20000000-0000-4000-8000-000000000103', '10000000-0000-4000-8000-000000000001',
   '大出公園', 'view', 36.696993, 137.871295,
   '吊橋と姫川と白馬三山が一枚に収まる',
   '姫川に架かる大出吊橋の向こうに白馬三山がそびえる、村を代表する風景の公園。全長38.5mの大出吊橋のほかにも吊橋があり、茅葺き屋根の古民家や水車小屋、眺望テラス、遊歩道が点在する。園内に駐車場があり、桜は4月下旬〜5月上旬、紅葉は10月中旬〜下旬が見頃。',
   '冬（11月下旬〜4月上旬）は公園のトイレが閉まるので、先に済ませておく',
   '4月下旬〜5月上旬（桜）、10月中旬〜下旬（紅葉）', 30, array['吊橋', '白馬三山', '桜', '紅葉'], 4.5, 2, null),
  ('20000000-0000-4000-8000-000000000104', '10000000-0000-4000-8000-000000000001',
   '姫川源流自然探勝園', 'nature', 36.626446, 137.847860,
   '国道のすぐそばで湧く、名水百選の川の始まり',
   '日本海へ注ぐ姫川の源流で、環境省の名水百選。ハンノキ林の中に湧き水がいくつもあり、国道沿いで大きな川の源流が見られるのは全国でも珍しい。園内には1周約1時間30分の散策路があり、隣の親海湿原ではフクジュソウの群生やバイカモなど150種を超える植物が見られる。',
   '園内は自転車に乗り入れできないので、歩いて回る',
   '4月〜11月（例年の見頃）', 90, array['名水百選', '湧き水', '湿原', '散策'], 4.0, 3, null),
  ('20000000-0000-4000-8000-000000000105', '10000000-0000-4000-8000-000000000001',
   '白馬ガラス工房GAKU', 'craft', 36.694788, 137.847538,
   '11種類の模様から選ぶ、とんぼ玉づくり',
   '白馬の自然に囲まれたガラス工房で、とんぼ玉づくりの体験ができる。模様は11種類から選べ、小学1年生から参加できる（模様によっては6歳から）。体験は予約制で、ホームページか電話で受け付ける。白馬駅から車で5分、八方バスターミナルから歩いて10分弱。',
   '屋内の体験なので雨の日の過ごし方に向く。受付は15:30まで',
   '通年（火曜定休、水曜は不定休）', 60, array['とんぼ玉', 'ガラス', '体験', '雨の日'], 4.0, 4, null),
  ('20000000-0000-4000-8000-000000000106', '10000000-0000-4000-8000-000000000001',
   '貞麟寺', 'history', 36.640012, 137.839574,
   '麻を蒔く頃に満開になる「麻蒔糸桜」',
   '神城の寺で、境内の枝垂れ桜はエドヒガン系の古木として村の天然記念物。満開の頃が麻の種を蒔く目安だったことから「麻蒔糸桜（おまきいとざくら）」と呼ばれてきた。オオヤマザクラやエドヒガンも咲き、境内脇の草地はカタクリの群生地。例年の見頃は4月下旬〜5月上旬。',
   '桜の頃は、境内脇の草地に咲くカタクリも見ておきたい',
   '4月下旬〜5月上旬（桜）', 30, array['枝垂れ桜', '天然記念物', 'カタクリ'], 4.0, 4, null),
  ('20000000-0000-4000-8000-000000000107', '10000000-0000-4000-8000-000000000001',
   'おやきの山愛', 'gourmet', 36.690380, 137.836990,
   '赤い暖簾が目印の、手作りおやきの店',
   'エコーランドにある、赤い暖簾が目印の手作りおやきの店。生地は小麦粉と大麦粉で、そば粉は使っていない。全10種類に季節限定の味が加わり、店内の喫茶スペースではおやきセットや抹茶おやきセットを味わえる。冷凍おやきのお土産や全国発送もあり、店は朝8時から開く。',
   '朝8時から開いているので、出かける前の朝ごはんにもなる',
   '通年（8:00〜17:00）', 30, array['おやき', '郷土の味', 'テイクアウト'], 4.0, 4, null),
  ('20000000-0000-4000-8000-000000000108', '10000000-0000-4000-8000-000000000001',
   'Kitchen＆Marché 農かふぇ', 'gourmet', 36.668746, 137.848649,
   '農場直営の、野菜とごはんが主役のランチ',
   '神城の農場が営むカフェで、自分たちで収穫した野菜のおかずと精米したての米のごはんを出す。人気は野菜スープカレー。JGAP 認証の農場の米と野菜を使い、「信州食育発信 3つの星レストラン」にも登録されている。店内の売店では米・野菜・加工品が買え、テラス席もある。',
   '7月・8月はブルーベリー園の営業にあわせて無休になる',
   '通年のランチ（木曜定休、7〜8月は無休）', 60, array['農家カフェ', 'ランチ', '地元野菜'], 4.0, 4, null),
  -- 大町市
  ('20000000-0000-4000-8000-000000000201', '10000000-0000-4000-8000-000000000002',
   '塩の道ちょうじや', 'history', 36.504188, 137.858116,
   '塩問屋の屋敷に残る「にがりだめ」',
   '江戸時代に松本藩から塩問屋を任された平林家の住宅で、千国街道（塩の道）の宿場町・大町宿の歴史を伝える。建物は国の登録有形文化財で、明治23年に建てられた母屋が残り、塩蔵には塩からにじむにがりを溜める「にがりだめ」が当時のまま残る。見学は30〜40分ほど。',
   '館内のカフェは10時〜15時。夏は松田牛乳のミルクかき氷が人気',
   '通年（水曜休館）', 40, array['塩の道', '登録有形文化財', '資料館'], 4.0, 4, null),
  ('20000000-0000-4000-8000-000000000202', '10000000-0000-4000-8000-000000000002',
   '若一王子神社', 'history', 36.516697, 137.852859,
   '神社に三重塔が立つ、仁科氏の守り神',
   '市街地の北のはずれにある仁科氏の守護神で、安土桃山時代の様式を残す本殿は国の重要文化財。境内には県宝の三重塔が立ち、神社の中に仏塔がある神仏習合の姿を今に伝える。7月の例祭では少年の射手が市内を進みながら的を射る「子ども流鏑馬」が行われる。',
   '7月の例祭では、子ども流鏑馬と舞台（山車）が市内を巡る',
   '通年（例祭は7月の第4日曜とその前日）', 30, array['重要文化財', '三重塔', '流鏑馬'], 4.0, 3, null),
  ('20000000-0000-4000-8000-000000000203', '10000000-0000-4000-8000-000000000002',
   'ぽかぽかランド美麻', 'onsen', 36.605372, 137.895528,
   '湯上がりに手打ちそば、山あいの道の駅の湯',
   '美麻の山あいにある、日帰り温泉と宿泊施設をもつ道の駅。単純温泉の大浴場に露天風呂とサウナ、北投石を使った「北投石の湯」がある。日帰り入浴は10時〜21時（最終受付20時30分）。安曇野 IC から車で約30分、信濃大町駅からはバスで約20分。',
   '湯上がりに、道の駅の手打ちそばを食べて帰れる',
   '通年（10:00〜21:00）', 90, array['日帰り温泉', '道の駅', '露天風呂', 'そば'], 3.5, 4, null),
  ('20000000-0000-4000-8000-000000000204', '10000000-0000-4000-8000-000000000002',
   'ゆいせきや', 'craft', 36.501057, 137.860306,
   '手ぶらで作れる、一閑張りの小物',
   '身近な材料で、暮らしに使える小物を作る体験ができる店。材料と道具がそろっているので手ぶらで参加でき、体験は1回1,000円から（要予約）。店内では一閑張りのカゴや小物を売り、地元の作家の作品も展示している。一閑張りは竹や木の骨組みに和紙を張り重ね、柿渋を塗って仕上げる手工芸。',
   '休みは火・水・日曜と祝日。予約してから訪ねる',
   '通年（火・水・日曜・祝日は休み）', 90, array['一閑張り', '体験', '地元作家'], 4.0, 5, null),
  ('20000000-0000-4000-8000-000000000205', '10000000-0000-4000-8000-000000000002',
   '創舎 わちがい', 'gourmet', 36.505314, 137.858261,
   '大庄屋の屋敷でいただく「塩の道お祭りご膳」',
   '室町時代からこの地にある栗林家の屋号「わちがい」を継ぐ、築130年以上の大庄屋の屋敷を使った食事処。名物は塩の道の宿場町の様子を伝える郷土料理「塩の道お祭りご膳」。2階はギャラリーで、季節ごとに地元の作家の作品展を開く。信濃大町駅から歩いて10分。',
   '終日予約制。お祭りご膳は予約のときに伝えておく',
   '通年の昼（10:00〜16:00、火曜・第4月曜は休み）', 60, array['郷土料理', '古民家', '塩の道'], 4.0, 3, null),
  ('20000000-0000-4000-8000-000000000206', '10000000-0000-4000-8000-000000000002',
   '居谷里湿原', 'nature', 36.545374, 137.854115,
   '5月に「春の紅葉」をするハナノキの湿原',
   '幅130m・長さ500mの湿原で、県の天然記念物。周りの遊歩道は花を見ながら1時間ほどで一周できる。4月はザゼンソウやミズバショウ、5月上旬は芽吹きのハナノキが赤く色づき、梅雨時はカキツバタやアヤメが咲く。日本最小のトンボ・ハッチョウトンボも見られる。',
   '5月上旬、ハナノキが赤く染まる「春の紅葉」はここならでは',
   '4月〜梅雨時（花の季節）', 60, array['湿原', '天然記念物', 'ミズバショウ', '散策'], 4.0, 4, null),
  ('20000000-0000-4000-8000-000000000207', '10000000-0000-4000-8000-000000000002',
   '中綱湖', 'nature', 36.596890, 137.843740,
   '湖面に映る濃いピンクのオオヤマザクラ',
   '仁科三湖のひとつで、四季の景色が湖面に映る「リフレクション」の撮影地として観光協会が穴場と紹介する。4月下旬〜5月上旬のゴールデンウィーク前後には、湖面に映る濃いピンクのオオヤマザクラを撮ろうと写真好きが集まる。全面結氷した冬はワカサギの穴釣りもでき、解禁は観光協会のサイトで知らせる。',
   '桜の時期は路上駐車や周りの民有地への立ち入りをしない。駐車場は大町市観光協会の案内で確かめてから',
   '4月下旬〜5月上旬（オオヤマザクラ）', 30, array['仁科三湖', 'オオヤマザクラ', 'リフレクション'], 4.0, 3, null),
  ('20000000-0000-4000-8000-000000000208', '10000000-0000-4000-8000-000000000002',
   '鷹狩山', 'view', 36.506672, 137.886841,
   '白馬岳から常念岳まで、北アルプスを端から端まで',
   '市街地の東にある山で、山頂の展望台から北は白馬岳、南は常念岳まで北アルプスの山並みを一望できる。10月下旬〜11月上旬は雲海が出やすく、雪化粧の時期は朝焼けに染まる連山が美しい。夜景の眺めや「恋人の聖地」の施設もある。信濃大町駅から車で20分で、冬は道が通行止めになる。',
   '雲海をねらうなら、雨の翌日に晴れた朝。市のライブカメラで山頂の様子を見てから行ける',
   '10月下旬〜11月上旬の朝（雲海）。冬期は通行止め', 30, array['展望台', '雲海', '北アルプスの眺め'], 4.5, 3, null),
