values
  -- 東川町
  ('20000000-0000-4000-8000-000000000601', '10000000-0000-4000-8000-000000000006',
   '旭岳', 'view', 43.6520095, 142.7995737,
   '日本でいちばん早い紅葉へ、ロープウェイで',
   '標高2,291mの北海道の最高峰で、日本百名山の一つ。日本で最も早く紅葉が訪れる場所として知られ、9月中旬から10月初旬が見頃。標高約1,100mの旭岳温泉から標高約1,600mの姿見駅まではロープウェイで約10分で、高山植物は7月下旬に向けて盛りを迎える。',
   'ロープウェイは整備で運休する期間がある。旭岳ロープウェイの駐車場は夏は有料で、11〜5月は無料',
   '7月下旬（高山植物）、9月中旬〜10月初旬（紅葉）', 150, array['日本百名山', 'ロープウェイ', '紅葉', '高山植物'], 4.5, 2, null),
  ('20000000-0000-4000-8000-000000000602', '10000000-0000-4000-8000-000000000006',
   '忠別湖', 'view', 43.6277302, 142.6298592,
   '風のない日、湖面に旭岳が映る',
   '忠別川の上流、旭川市の中心部と旭岳の間にある忠別ダムの湖。無風の日は鏡のような湖面に旭岳が映り、高さ14.8mの「七色の噴水」には晴れた日に虹がかかる。カヤックやSUP、釣り、サイクリングもでき、湖畔には東屋や砂浜の親水広場がある。',
   '噴水の虹は夏の朝が狙い目。太陽の角度や天気で見えないこともある',
